<script>
    function switchTab(event, pageName) {
        const tabContent = document.querySelector('.tab-content');
        const pages = tabContent.querySelectorAll('.page');
        pages.forEach(page => page.classList.remove('active'));

        const tabs = document.querySelector('.tabs');
        const tabButtons = tabs.querySelectorAll('.tab-button');
        tabButtons.forEach(button => button.classList.remove('active'));

        document.getElementById(pageName).classList.add('active');
        event.currentTarget.classList.add('active');
    }

    function SafeGetValue(obj, path, defaultValue = "N/A") {
        if (typeof path !== 'string') return defaultValue;
        let keys = path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        return current === undefined || current === null ? defaultValue : current;
    }

    // 新增：处理|||分隔符的通用函数
    function formatWithSeparators(text) {
        if (typeof text !== 'string') {
            // 如果是数组就先转为字符串
            text = Array.isArray(text) ? text.join('|||') : String(text);
        }
        // 分割并转换为换行
        return text
            .split('|||')
            .map(line => line.trim())
            .filter(line => line)
            .join('<br>');
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data || !messages[0].data.stat_data) {
                const errorMsg = "无法加载状态数据。";
                document.getElementById('live-room-name').innerText = errorMsg;
                document.getElementById('char-name-identity').innerText = errorMsg;
                return;
            }

            const allData = messages[0].data.stat_data;

            // --- 处理女角色页签 ---
            const charKey = '女角色';
            if (allData && allData[charKey]) {
                const char = allData[charKey];
                const name = SafeGetValue(char, '名称.0', '待选定女角色');
                const identity = SafeGetValue(char, '出处身份.0', '无');
                const services_raw = SafeGetValue(char, '特殊服务.0', ['无']);
                const unacceptables_raw = SafeGetValue(char, '不可接受内容.0', ['无']);

                // 修复：使用通用函数处理特殊服务的|||分隔符
                const services = formatWithSeparators(services_raw);
                // 对不可接受内容也做同样处理
                const unacceptables = formatWithSeparators(unacceptables_raw);

                document.getElementById('char-name-identity').innerText = `${name} (${identity})`;
                // 使用innerHTML才能解析<br>标签
                document.getElementById('char-services').innerHTML = services || '无';
                document.getElementById('char-unacceptables').innerHTML = unacceptables || '无';
            } else {
                document.getElementById('char-name-identity').innerText = "角色数据缺失。";
            }

            // --- 处理直播间页签 ---
            const liveKey = '直播间';
            if (allData && allData[liveKey]) {
                const live = allData[liveKey];
                const roomName = SafeGetValue(live, '房间名.0', '未知房间');
                const hotValue = SafeGetValue(live, '热度.0', '0');
                const content = SafeGetValue(live, '直播内容.0', '（无直播内容）');
                const danmakusString = SafeGetValue(live, '弹幕列表.0', '（暂无弹幕）');

                document.getElementById('live-room-name').innerText = roomName;
                document.getElementById('live-hot-value').innerText = `热度：${hotValue}`;
                document.getElementById('live-content-display').innerText = content;

                const danmakuListElement = document.getElementById('live-danmaku-list');

                if (typeof danmakusString === 'string' && danmakusString.trim() !== '' && danmakusString !== '（暂无弹幕）') {
                    // 复用通用函数处理弹幕
                    const danmakuHTML = formatWithSeparators(danmakusString);
                    danmakuListElement.innerHTML = danmakuHTML;
                } else {
                    danmakuListElement.innerText = '（暂无弹幕）';
                }

            } else {
                document.getElementById('live-room-name').innerText = "直播间数据缺失。";
            }

        } catch (error) {
            const errorText = `状态栏加载出错: ${error.message}`;
            console.error(errorText, error);
            const statusContainer = document.querySelector('.status-container');
            if(statusContainer) {
                statusContainer.innerHTML = `<div style='padding: 20px; color: red;'>${errorText}</div>`;
            }
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>

</body>
</html>
